-- HyprMod configuration harness.
--
-- Executes a Hyprland Lua configuration with a recording implementation of the
-- `hl` API and reports everything the compositor would have been told, as JSON.
-- This is how HyprMod reads the *effective* configuration: resolved values,
-- binds generated by loops, rules built from variables, and so on.
--
-- Environment:
--   HYPRMOD_ENTRY  absolute path to the entry file (hyprland.lua)
--   HYPRMOD_OUT    file to write the JSON report to
--
-- The harness never invokes user callbacks (hl.on / hl.timer); it records the
-- registration, matching what happens while Hyprland loads a config. It does not
-- expose os.execute/io writes to the evaluated configuration.

local ENTRY = os.getenv("HYPRMOD_ENTRY")
local OUT = os.getenv("HYPRMOD_OUT")

local getinfo = debug.getinfo
local realdebug = debug

-- ---------------------------------------------------------------- utilities

local function sourceOf(level)
	local i = getinfo(level + 1, "Sl")
	if not i then
		return "", 0
	end
	local src = i.source or i.short_src or ""
	src = src:gsub("^@", "")
	return src, i.currentline or 0
end

local function isArray(t)
	local n = 0
	for k in pairs(t) do
		if type(k) ~= "number" or k < 1 or k ~= math.floor(k) then
			return false
		end
		if k > n then
			n = k
		end
	end
	for i = 1, n do
		if t[i] == nil then
			return false
		end
	end
	return true, n
end

local escapeMap = {
	['"'] = '\\"', ["\\"] = "\\\\", ["\n"] = "\\n", ["\r"] = "\\r",
	["\t"] = "\\t", ["\b"] = "\\b", ["\f"] = "\\f",
}

local function quote(s)
	return '"' .. s:gsub('[%z\1-\31\\"]', function(c)
		return escapeMap[c] or string.format("\\u%04x", c:byte())
	end) .. '"'
end

local function numberStr(n)
	if n ~= n or n == math.huge or n == -math.huge then
		return "null"
	end
	if n == math.floor(n) and math.abs(n) < 2 ^ 53 then
		return string.format("%d", n)
	end
	return string.format("%.14g", n)
end

local encodeValue

-- encodeList always emits a JSON array, including for empty tables, which is
-- what dispatcher argument lists need.
local function encodeList(t, seen, depth)
	local n = 0
	for k in pairs(t) do
		if type(k) == "number" and k > n then
			n = k
		end
	end
	local parts = {}
	for i = 1, n do
		parts[i] = encodeValue(t[i], seen, depth + 1)
	end
	return "[" .. table.concat(parts, ",") .. "]"
end

local JsonArray = {}

local function asArray(t)
	local out = setmetatable({}, JsonArray)
	for i, v in ipairs(t or {}) do
		out[i] = v
	end
	return out
end

local function encode(v, seen, depth)
	local tv = type(v)
	if v == nil then
		return "null"
	elseif tv == "boolean" then
		return v and "true" or "false"
	elseif tv == "number" then
		return numberStr(v)
	elseif tv == "string" then
		return quote(v)
	elseif tv == "table" then
		if seen[v] or depth > 24 then
			return "null"
		end
		seen[v] = true
		local out
		if getmetatable(v) == JsonArray then
			out = encodeList(v, seen, depth + 1)
		elseif v.__dsp ~= nil then
			-- Dispatcher marker produced by hl.dsp.
			out = '{"name":' .. quote(tostring(v.__dsp)) .. ',"args":' .. encodeList(v.__args or {}, seen, depth + 1) .. "}"
		else
			local arr, n = isArray(v)
			if arr and n > 0 then
				local parts = {}
				for i = 1, n do
					parts[i] = encodeValue(v[i], seen, depth + 1)
				end
				out = "[" .. table.concat(parts, ",") .. "]"
			else
				local parts = {}
				for k, val in pairs(v) do
					local kk = type(k) == "string" and k or tostring(k)
					if tv ~= "function" then
						parts[#parts + 1] = quote(kk) .. ":" .. encodeValue(val, seen, depth + 1)
					end
				end
				out = "{" .. table.concat(parts, ",") .. "}"
			end
		end
		seen[v] = nil
		return out
	elseif tv == "function" then
		local src, line = sourceOf(3)
		return '{"__function":true,"file":' .. quote(src) .. ',"line":' .. line .. "}"
	else
		return "null"
	end
end

encodeValue = encode

-- --------------------------------------------------------------- recording

local rec = {
	config = {},
	monitors = {},
	binds = {},
	window_rules = {},
	layer_rules = {},
	workspace_rules = {},
	curves = {},
	animations = {},
	gestures = {},
	devices = {},
	envs = {},
	permissions = {},
	events = {},
	timers = {},
	dispatches = {},
	execs = {},
	requires = {},
	files = {},
	errors = {},
	logs = {},
}

local function record(list, entry)
	local src, line = sourceOf(3)
	entry.file = src
	entry.line = line
	list[#list + 1] = entry
	return #list
end

local function makeHandle(list, idx)
	local h = {}
	local function setEnabled(...)
		local args = { ... }
		local enabled
		for _, a in ipairs(args) do
			if type(a) == "boolean" then
				enabled = a
			end
		end
		if enabled == nil then
			enabled = true
		end
		if list[idx] then
			list[idx].enabled = enabled
		end
	end
	h.set_enabled = setEnabled
	return h
end

-- ------------------------------------------------------------- config tree

-- Accumulated config so hl.get_config can read back what was set.
local configTree = {}

local function deepMerge(dst, src)
	for k, v in pairs(src) do
		if type(v) == "table" and type(dst[k]) == "table" then
			deepMerge(dst[k], v)
		else
			dst[k] = v
		end
	end
	return dst
end

-- ------------------------------------------------------------------ hl API

local hl = {}

function hl.config(tbl)
	record(rec.config, { table = tbl })
	deepMerge(configTree, tbl or {})
end

function hl.get_config(key)
	if key == nil then
		return configTree
	end
	local node = configTree
	for part in tostring(key):gmatch("[^.]+") do
		if type(node) ~= "table" then
			return nil, "unknown config key"
		end
		node = node[part]
	end
	return node
end

function hl.monitor(spec)
	record(rec.monitors, { spec = spec })
end

local function dspOf(d)
	if type(d) == "table" and d.__dsp ~= nil then
		return { name = tostring(d.__dsp), args = asArray(d.__args) }
	elseif type(d) == "function" then
		return { name = "<function>", args = asArray({}) }
	end
	return { name = tostring(d), args = asArray({}) }
end

function hl.bind(keys, dispatcher, opts)
	local idx = record(rec.binds, {
		keys = tostring(keys),
		dsp = dspOf(dispatcher),
		opts = opts or {},
		enabled = true,
	})
	return makeHandle(rec.binds, idx)
end

function hl.unbind(keys)
	keys = tostring(keys)
	for _, bind in ipairs(rec.binds) do
		if bind.keys == keys then
			bind.enabled = false
		end
	end
	rec.dispatches[#rec.dispatches + 1] = { unbind = keys }
end

function hl.window_rule(spec)
	local idx = record(rec.window_rules, { spec = spec, enabled = true })
	return makeHandle(rec.window_rules, idx)
end

function hl.layer_rule(spec)
	local idx = record(rec.layer_rules, { spec = spec, enabled = true })
	return makeHandle(rec.layer_rules, idx)
end

function hl.workspace_rule(spec)
	local idx = record(rec.workspace_rules, { spec = spec, enabled = true })
	return makeHandle(rec.workspace_rules, idx)
end

function hl.curve(name, spec)
	record(rec.curves, { name = tostring(name), spec = spec })
end

function hl.animation(spec)
	record(rec.animations, { spec = spec })
end

function hl.gesture(spec)
	record(rec.gestures, { spec = spec })
end

function hl.device(spec)
	record(rec.devices, { spec = spec })
end

function hl.env(name, value)
	record(rec.envs, { name = tostring(name), value = tostring(value) })
end

function hl.permission(a, b, c)
	if type(a) == "table" then
		record(rec.permissions, { binary = tostring(a.binary or ""), type = tostring(a.type or ""), mode = tostring(a.mode or a.permission or "") })
	else
		record(rec.permissions, { binary = tostring(a), type = tostring(b), mode = tostring(c) })
	end
end

function hl.on(event, cb)
	record(rec.events, { event = tostring(event), hasCallback = type(cb) == "function" })
	return { cancel = function() end }
end

function hl.timer(cb, opts)
	record(rec.timers, { opts = opts or {} })
	return { cancel = function() end }
end

function hl.dispatch(d)
	record(rec.dispatches, { dsp = dspOf(d) })
end

function hl.exec_cmd(cmd, rules)
	record(rec.execs, { cmd = tostring(cmd), rules = rules or {} })
end

function hl.exec_raw(cmd, rules)
	record(rec.execs, { cmd = tostring(cmd), rules = rules or {}, raw = true })
end

function hl.exec_scheduled_prop_refresh_immediately() end
function hl.clear_crashed_lockscreen() end
function hl.define_submap(name, a, b) end

function hl.version()
	return "hyprmod-sandbox"
end

-- Getters return neutral values: callbacks are not executed during load, but a
-- config may call them at top level.
function hl.get_active_monitor() return nil end
function hl.get_active_window() return nil end
function hl.get_last_window() return nil end
function hl.get_urgent_window() return nil end
function hl.get_cursor_pos() return nil end
function hl.get_monitor_at_cursor() return nil end
function hl.get_monitor() return nil end
function hl.get_monitor_at() return nil end
function hl.get_monitors() return {} end
function hl.get_active_workspace() return nil end
function hl.get_active_special_workspace() return nil end
function hl.get_last_workspace() return nil end
function hl.get_workspace() return nil end
function hl.get_workspaces() return {} end
function hl.get_workspace_windows() return {} end
function hl.get_windows() return {} end
function hl.get_window() return nil end
function hl.get_layers() return {} end
function hl.get_loaded_plugins() return {} end
function hl.get_current_submap() return "" end
function hl.is_key_down() return false end

-- hl.dsp namespace: any path resolves to a callable that records its name.
local function makeDsp(prefix)
	return setmetatable({}, {
		__index = function(_, k)
			if k == "__dsp" or k == "__args" then
				return nil
			end
			local child = (prefix == "" and k) or (prefix .. "." .. k)
			return makeDsp(child)
		end,
		__call = function(_, ...)
			return { __dsp = prefix, __args = { ... } }
		end,
	})
end

hl.dsp = makeDsp("")

hl.notification = setmetatable({}, {
	__index = function()
		return function() return {} end
	end,
})

hl.plugin = setmetatable({}, {
	__index = function()
		return function() return {} end
	end,
})

hl.layout = setmetatable({}, {
	__index = function(_, k)
		if k == "register" or k == "unregister" then
			return function(name, provider)
				rec.layouts = rec.layouts or {}
				record(rec.layouts, { name = tostring(name) })
				return name
			end
		end
		return function() end
	end,
})

-- ------------------------------------------------------------------- require

local ROOT = ENTRY:match("^(.*)[/\\][^/\\]*$") or "."
local moduleCache = {}
local loadStack = {}
local MAX_DEPTH = 10

local function fileExists(p)
	local f = io.open(p, "r")
	if not f then
		return false
	end
	f:close()
	return true
end

local function readFile(p)
	local f = io.open(p, "r")
	if not f then
		error("cannot open " .. p, 2)
	end
	local content = f:read("a")
	f:close()
	return content
end

local function resolveModule(path)
	local candidates = {}
	if path:sub(1, 1) == "/" then
		candidates = { path, path .. ".lua", path .. "/init.lua" }
	else
		local rel = path:gsub("%.", "/")
		candidates = {
			ROOT .. "/" .. path .. ".lua",
			ROOT .. "/" .. path,
			ROOT .. "/" .. rel .. ".lua",
			ROOT .. "/" .. rel .. "/init.lua",
		}
	end
	for _, c in ipairs(candidates) do
		if fileExists(c) then
			return c
		end
	end
	return nil
end

local env -- forward declaration; assigned below

local function runChunk(content, name, depth)
	local chunk, err = load(content, "@" .. name, "t", env)
	if not chunk then
		return false, err
	end
	local ok, res = xpcall(chunk, function(e)
		return tostring(e) .. "\n" .. (realdebug.traceback("", 2) or "")
	end)
	if not ok then
		return false, res
	end
	return true, res
end

local function requireModule(mod)
	local resolved = resolveModule(mod)
	if not resolved then
		error("module '" .. tostring(mod) .. "' not found", 2)
	end
	if moduleCache[resolved] ~= nil then
		return moduleCache[resolved]
	end
	for _, active in ipairs(loadStack) do
		if active == resolved then
			error("cycle detected requiring '" .. tostring(mod) .. "'", 2)
		end
	end
	if #loadStack >= MAX_DEPTH then
		error("require depth limit exceeded", 2)
	end
	rec.requires[#rec.requires + 1] = resolved
	rec.files[resolved] = true
	loadStack[#loadStack + 1] = resolved
	local content = readFile(resolved)
	local ok, res = runChunk(content, resolved, #loadStack)
	loadStack[#loadStack] = nil
	if not ok then
		error(res, 2)
	end
	if res == nil then
		res = true
	end
	moduleCache[resolved] = res
	return res
end

local function dofileModule(path)
	local resolved = path
	if path:sub(1, 1) ~= "/" then
		resolved = ROOT .. "/" .. path
	end
	if not fileExists(resolved) and fileExists(resolved .. ".lua") then
		resolved = resolved .. ".lua"
	end
	if not fileExists(resolved) then
		error("cannot open " .. tostring(path), 2)
	end
	rec.files[resolved] = true
	local ok, res = runChunk(readFile(resolved), resolved, 1)
	if not ok then
		error(res, 2)
	end
	return res
end

-- --------------------------------------------------------------------- env

local realOpen = io.open

env = {
	hl = hl,
	_VERSION = _VERSION,
	assert = assert,
	error = error,
	ipairs = ipairs,
	next = next,
	pairs = pairs,
	pcall = pcall,
	xpcall = xpcall,
	print = function(...)
		local parts = {}
		for i = 1, select("#", ...) do
			parts[i] = tostring((select(i, ...)))
		end
		rec.logs[#rec.logs + 1] = table.concat(parts, "\t")
	end,
	rawequal = rawequal,
	rawget = rawget,
	rawlen = rawlen,
	rawset = rawset,
	select = select,
	setmetatable = setmetatable,
	getmetatable = getmetatable,
	tonumber = tonumber,
	tostring = tostring,
	type = type,
	string = string,
	table = table,
	math = math,
	utf8 = utf8,
	load = function(chunk, name, mode, e)
		return load(chunk, name, mode, e or env)
	end,
	loadstring = function(chunk, name)
		return load(chunk, name, "t", env)
	end,
	require = requireModule,
	dofile = dofileModule,
	loadfile = function(path, mode, e)
		local resolved = path
		if path:sub(1, 1) ~= "/" then
			resolved = ROOT .. "/" .. path
		end
		if not fileExists(resolved) then
			return nil, "cannot open " .. tostring(path)
		end
		rec.files[resolved] = true
		return load(readFile(resolved), "@" .. resolved, "t", e or env)
	end,
	os = {
		getenv = os.getenv,
		date = os.date,
		time = os.time,
		clock = os.clock,
		difftime = os.difftime,
		exit = function() error("os.exit is not available", 2) end,
	},
	io = {
		open = function() return nil, "io is not available" end,
		write = function() return nil, "io is not available" end,
		read = function() return nil end,
		close = function() end,
		lines = function() error("io is not available", 2) end,
	},
	collectgarbage = function() return 0 end,
}

env._G = env
env.require = requireModule
env.package = { loaded = moduleCache, path = ROOT .. "/?.lua" }

-- ------------------------------------------------------------------- runner

if not ENTRY then
	io.stderr:write("HYPRMOD_ENTRY not set\n")
	os.exit(2)
end

-- Keep a private handle to the raw reader for the harness itself.
local function harnessRead(p)
	local f = realOpen(p, "r")
	if not f then
		return nil
	end
	local c = f:read("a")
	f:close()
	return c
end

local budgetExceeded = false
local function installBudget()
	local ok = realdebug.sethook(function()
		budgetExceeded = true
		error("instruction budget exceeded", 2)
	end, "", 50000000)
	return ok
end

rec.entry = ENTRY
rec.files[ENTRY] = true

local entryContent = harnessRead(ENTRY)
if not entryContent then
	rec.errors[#rec.errors + 1] = { message = "entry file not found: " .. ENTRY }
else
	installBudget()
	realdebug.sethook()
	-- Re-arm the hook only for the configured chunk.
	budgetExceeded = false
	realdebug.sethook(function()
		error("instruction budget exceeded", 2)
	end, "", 50000000)
	local ok, err = runChunk(entryContent, ENTRY, 0)
	realdebug.sethook()
	if not ok then
		rec.errors[#rec.errors + 1] = { message = tostring(err) }
	end
end

-- ------------------------------------------------------------------ output

local parts = {}
local function emit(k, v)
	parts[#parts + 1] = quote(k) .. ":" .. v
end

emit("entry", quote(ENTRY))
emit("root", quote(ROOT))
emit("version", quote(_VERSION))

local listNames = {
	"config", "monitors", "binds", "window_rules", "layer_rules",
	"workspace_rules", "curves", "animations", "gestures", "devices",
	"envs", "permissions", "events", "timers", "dispatches", "execs",
	"errors", "logs",
}
local seen = {}
for _, name in ipairs(listNames) do
	emit(name, encodeList(rec[name], seen, 0))
end
emit("requires", encodeList(rec.requires, seen, 0))
local fileList = {}
for f in pairs(rec.files) do
	fileList[#fileList + 1] = f
end
table.sort(fileList)
emit("files", encodeList(fileList, seen, 0))

local json = "{" .. table.concat(parts, ",") .. "}"

if OUT then
	local f = realOpen(OUT, "w")
	if f then
		f:write(json)
		f:close()
	else
		io.stderr:write("cannot write report to " .. OUT .. "\n")
	end
else
	io.write(json)
end
